#!/bin/sh
set -eu

TMP=/tmp/pibic-alpinews-v3-real.sh
PAYLOAD=/tmp/pibic-alpinews-v3.payload

cat > "$PAYLOAD" <<'PAYLOAD_EOF'

PAYLOAD_EOF

# Verifica se o payload chegou inteiro antes de executar.
ACTUAL=$(sha256sum "$PAYLOAD" | awk '{print $1}')
EXPECTED=5d92de07ec9682f1c932268295866814ca101ecab5ca764f346ac850a769f23d
if [ "$ACTUAL" != "$EXPECTED" ]; then
    echo "[ERRO] Payload do update corrompido."
    echo "Esperado: $EXPECTED"
    echo "Recebido: $ACTUAL"
    exit 1
fi

base64 -d "$PAYLOAD" | gzip -d > "$TMP"
chmod +x "$TMP"
rm -f "$PAYLOAD"

ACTUAL_SCRIPT=$(sha256sum "$TMP" | awk '{print $1}')
EXPECTED_SCRIPT=df119a40c92a5d5b99a8870ac53686dd0e0ed330a8f60b4b1d4b97877ef37850
if [ "$ACTUAL_SCRIPT" != "$EXPECTED_SCRIPT" ]; then
    echo "[ERRO] Script decodificado nao confere."
    exit 1
fi

exec sh "$TMP"
